INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','ئەم دوێنە دەربارەی چۆنییەتی کەردن زیاتەر زعفران بۆ عێراق ئامادەی بۆ سەبزیگەرییە. زانیارییەکانی ورد لەگەڵ تەکنیکی خەریکە کەسی و ڕوونکردنەوەی تەکنیکە.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
