INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Чаро масофаи нории пайчаки чойчак дар кишт аз ҷиҳати муҳим будан дорад?</h2><p>Интихоби дуруст ва ҷойгиркунии нории пайчак (Drip Tape) ба яке аз унвурҳои асосии сафедроӣ дар обёробии қатрашояндаи маҳсулоти ҳассос монанди чойчак табдил ёфтааст. Чойчак ниҳоеест, ки решаҳояш сатҳироқтар аз бисёр дигар чигитонагон мебошад ва барои пешгирии стресси хушкӣ ва беморҳои заъфӣ ба намдирии доимии қабати сатҳии хок ниёз дорад. Агар масофа байни нориҳои пайчак ё масофаи чулбор аз решаҳо риоя нашавад, на танҳо об ба таври баробар тақсим намешавад, балки хароҷоти энергия ва помпагӣ зиёд мегардад. Дар идома, меъёрҳои техникӣ барои муайян кардани <strong>масофаи нории пайчак чойчак</strong> ро бо мукаммал муфассал мезанаем.</p><h3>Таърифҳои кӯтоҳи системаи нории пайчак</h3><p>Нории пайчак як намуди чулбори обёробии қатрашояндаи ягона аст, ки одатан ба таври доимӣ ё муваққатӣ дар замин ҷойгир карда мешавад ва пас аз охиршавии мавсим ҷамъ оварда мешавад. Тафовути ҷоҳазиркунии чулбори қатрашояндаи доимӣ, нории пайчак имконияти рафъи ҷойгиркунӣ дорад, ки барои давраи киштани ниҳояҳои солӣ монанди чойчак хеле корбарӣ аст. Муайян кардани дақиқи масофаи ин норҳо нисбат ба сафҳои кишт, калиди асосии ҳамвории рушди ниҳод дар тамоми сатҳи доронак мебошад.</p><h2>Меъёрҳои масофагузории нории пайчак вобаста ба намуди кишт</h2><p>Масофаи тавсияшуда барои нории пайчак дар киштани чойчак пурра вобаста ба усули ҷамъоварӣ ва ҷойгиркунии сафҳои кишт аст. Ба таври умумӣ, деҳқонон бо ду усули киштани сафӣ ва паҳншуда муомила мекунанд, аммо усули сафӣ барои обёробии қатрашоянда мувофиқтар аст.</p><h3>Масофаи чулбор нисбат ба сафи кишт (Offset)</h3><p>Муҳимтарин параметр дар масофаи нории пайчак, масофаи дарозии байни чулбор ва хати киштани тоҷӯҳон аст. Ин масофа хеле нест набояд, зеро метавонад боиси часидани нор ба решаи асосӣ гардида ва ба хуфъагирии реша оварда расонад. Аз тарафи дигар, агар масофа зиёд бошад, қобилияти ному (Wetting Zone) ба решаи асосӣ намерасад ва ниҳод маҷбур мегардад, ки энергияи бештарро барои ёфтани об сарф кунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-نخود-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت نخود: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop чойчак</figcaption></figure><ul><li><strong>Масофаи стандартӣ:</strong> Барои нориҳои пайчак бо суръати норҳои маъмул, масофаи 10 то 15 сантиметрӣ аз меҳвари сафи кишт мукаммал аст.</li><li><strong>Нор дар миёнаи саф:</strong> Дар баъзе системаҳои пешрафта, ду нор бо масофаи 30 сантиметрӣ аз меҳвари саф ҷойгир карда мешаванд, то ки таъмини намдирӣ аз ҳарду тарафи реша ҷамингардонида шавад.</li></ul><h3>Масофаи дарозии байни норҳо дар самти дарозии доронак</h3><p>Агар аз нориҳои доимӣ истифода карда шавад, ки дарозии онҳо маҳдуд аст, масофаи пайвасти норҳо ҳадди ақал 50 сантиметрӣ бошад, то ки оин об якдистрибуциягӣ тақсим шавад. Аммо агар мақсади масофа, ҷойгиркунии нориҳои параллел бо ҳам бошад, ин вобаста ба андозаи (Width of Bed) ҷамъоварии интихобшудаи шумо мебошад.</p><h3>Таъсири суръати норбаробарӣ ба масофаи нории пайчак</h3><p>Суръати охир шудан (Flow Rate) ба сантиметр дар соат омилест, ки бевосита ба масофаи иҷозатшуда байни сачаҳои обдор (Emitter Spacing) таъсир мерасонад. Барои кишт кардани нахӯд, сачаҳо бо масофаи 30 то 40 сантиметр аз ҳам тавсия дода мешаванд. Агар сачаҳо наздиктар бошанд, минтақаи намноки зудтар ташкил мешавад ва дарозии тӯҳми бандаро кӯтоҳтар кардан мумкин аст.</p><h2></h2><h2>Равонамои амалӣ барои ҷойгиркунии нории ғиллоҳӣ дар боғҳои нахӯд</h2><p>Дар амалиёт, пеш аз оғози оборӣ, бояд нақшаи дақиқи заминро кашед. Як хатогии оддӣ мувофиқ набудани дарозии нӯри ғиллоҳӣ бо дарозии қисми замин аст, ки боиси пайдои нуқтаҳои хушк дар охири нӯр мешавад. Барои ислоҳи ин мушкил, шумо метавонед аз шомгирҳои танзими фишор дар охири хатҳои иловагӣ истифода баред, то ки раёни об яксон боқӣ монад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-نخود-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت نخود: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>drip tape spacing row layout crop нахӯд</figcaption></figure><h3>Санҷиши чуқурии ғаллокашикунӣ ва масофаи амудӣ</h3><p>Масофаи нӯри ғиллоҳӣ бо нахӯд танҳо ҷанбаи уфуқӣ надорад. Чуқурии дараз кардани нӯр ё ҷойгирии он дар сатҳи хок низ бисёр муҳим аст. Барои нахӯд, тавсия дода мешавад, ки нӯрҳо ба таври сатҳӣ ё нимдараз (тақрибан 5 сантиметр) ҷойгир шаванд. Агар нӯр дар чуқури даразтар дараз карда шавад, динамикаи намноки хок тағйир меёбад ва метавонад намноки кофӣ ба сатҳи хок, ки ҷойи рушди дарахти асосии нахӯд аст, нарасад.</p><ul><li><strong>Кашт дар рӯи педи (Bedding) :</strong> Агар шумо аз педиҳои баланд барои кашти нахӯд истифода баред, масофаи нӯр бояд аз нӯки пед (Crest) тақрибан 20 то 25 сантиметр бошад, то ки реша дар канори пед, ки намнокӣ дар он баландтар аст, ҷойгир шавад.</li><li><strong>Кашти террасӣ:</strong> Дар минтақаҳои шубоб, масофаи нӯри ғиллоҳӣ набоист аз шумори замин пайравӣ кунад, то аз фишорҳои механикӣ ба нӯр пешгирӣ карда шавад.</li></ul><h3>Пайвасти мувофиқ ва пешгирии бозушадан</h3><p>Азбаски гулҳои легиноминезаӣ ба мисли нахӯд ба сироятҳои заҳрӣ ҳассосанд, бехишистонии системаи оборӣ тавассути масофаҳои мувофиқ ва суръати ҷараён нигоҳ дошта мешавад. Истифодаи парзакҳои мувофиқ дар сари воридшавии нӯри ғиллоҳӣ, умри сачаҳои обро зиёд мекунад.</p><h2></h2><h2>аналогӣ бо калонҳои дигар ва нуқтаҳои иловагӣ</h2><p>Диққат додан ба асосҳои обори қатрагӣ дар калони нахӯд, монанди асосҳое аст, ки барои маҳсулоти муҳими дигар, ба монанди <a href="https://navar-abyari.ir/miqdori-tuxmi-javori-donador-dar-yak-gektar/">тарзи калонкунии ҷаву ва миқдори токҳо дар гектар</a> ё ҳатто дар калонҳои барори, ба мисли системаи оборӣ барои соя истифода мешавад. Фарқияти асосӣ дар чуқурии решапарӣ ва эҳтиёҷи намнокӣ аст. Ҳамон тавре ки соя решаи чуқуртар дорад, нахӯд ба минтақаи намноки сатҳӣ эҳтиёҷ дорад. Инчунин, шинос шудан ба асосҳои умумии идоракунии захираҳои об дар калонҳои гуногун, ба монанди <a href="https://navar-abyari.ir/miqdori-tuxmi-lobiya-sabz-dar-yak-gektar-rahnamoi-kisht/">равишномаи обори сафедкунӣ</a> метавонад ба шумо биниши васеътар диҳад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-نخود-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت نخود: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>Фавоси лентаи қатрадорӣ, тарҳбандии сатҳ, афрот ва нӯшток</figcaption></figure><p>Яке аз хатогиҳои оддӣ, мутобиқ накардани фоси байни лентадори қатрадорӣ бо намуди хок аст. Дар хокҳои руда (шамоӣ), фоси байни сатҳҳо бояд камтар бошад (масалан, 25 сантиметр), зеро нобуди амудӣ тезтар аст, аммо дар хокҳои гилӣ, фоси 40 сантиметр мувофиқтар аст. Ин танзимот бевосита ба ҳаҷми поёнии ҳар гектар таъсир мерасонад ва метавонад муайян кунад, ки содири шумо чӣ қадар хоҳад буд.</p><h2></h2><h2>Саволҳои муштарак (FAQ) дар бораи фоси лентадори қатрадорӣ барои нӯшток</h2><ol><li><strong>Оё метавонам лентадори қатрадориро дар миёнаи сатҳи кбудкунии нӯшток ҷойгир кунам?</strong><br>Бале, агар аз лентадорҳо бо суръати нобудии баланд истифода баред, ҷойгир кардан дар марказ ё дар ду тараф бо фоси 10-15 сантиметр аз хати кбуд кардан иҷозат дорад ва ҳатто тавсия дода мешавад. Ин кор боиси менамояд, ки тарунокӣ тезтар ба соҳаи ободони аввалин бирасад.</li><li><strong>Фоси тӯлови лентадори қатрадорӣ чӣ таъсире ба истеъмоли энергия мерасонад?</strong><br>Ҳар чӣ қадар дарозии як хати паҳлуӣ (Lateral) зиёд бошад, паҳлишӣ камтар мешавад. Агар фоси лентадорҳои мувозӣ зиёд бошад ва шумо маҷбур шавед, ки аз лӯлаҳои асосии кӯтоҳтар истифода баред, хароҷоти насоб ва лӯлакунӣ кам мешавад, аммо бояд ба паҳлишӣ дар охири лентадор диққат диҳед.</li><li><strong>Беҳтарин вақт барои иваз кардани лентадори қатрадории кӯҳна дар кбудкунии нӯшток чист?</strong><br>Ҳамеша пеш аз кбуд. Чунки дар кбудкунии нӯшток, ободонии реша тез аст ва лентадори ҷигрида (порӣ) боиси бастани сатҳҳо ва задан ба вобастагӣҳои ободони аввалин менамояд.</li></ol><h3>Огоҳиҳои бехатарӣ дар насоб кардани фоси лентадори қатрадорӣ</h3><ul><li>Ҳаргиз лентадори қатрадориро дар наздикии мустақими маводи заҳролӣ ба хок ришт нагиред; фоси онро аз ҷои заррасонӣ нигоҳ доред.</li><li>Дар хокҳои вазнин, фоси лентадори қатрадории нӯштокро аз хатҳои шабрдакунӣ дур набаред, то аз хашинидани лентадор пешгирӣ шавад.</li></ul><h2>Хулоса ва тавсияҳои охирин</h2><p>Иктидории стандартҳои фоси лентадори қатрадорӣ дар кбудкунии нӯшток, таҳаммулро дар истифодабарии об то 30 ғиноз мекунад ва ба инкишофи якхелаи равонкунанда менамояд. Калиди асосӣ, мутобиқ кардани фоси сатҳҳои лентадор бо амикии нобуди хок ва намуди системаи кбуд кардан аст. Тавсия менамояд, ки пеш аз харидан, аз корхонаи истеҳсолкунандаи лентадори қатрадорӣ, диаграммаи кори гидроликии лентадори интихобкардаи худро даъоат кунед, то бар асоси дарозии қитъаи замин, беҳтарин фоси ва суръати нобудиро интихоб кунед. Иҷрои ин пешниҳодот, қадаме бомулоимет ба кишоварзӣи муосир ва устувор аст.</p>\n<p><strong>Мавзӯъҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d9%be%d9%86%d8%a8%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми поёни пахта дар гектар: пешниҳоди мукаммали кишоварзон</a>， <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%AA%D8%B1%DB%8C%D8%AA%DB%8C%DA%A9%D8%A7%D9%84%D9%87-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985D982D8AFD8A7D8B1 D8A8D8B0D8B1 D8AAD8B1DB8CD8AADB8CDAA9D8A7D984D987 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a></p>','Фосилии ҷинги тибри ҷӯғи кӯлакӣ: Стандардҳо ва муҳлати нӯшоии ҳатмӣ барои деҳқонони Тоҷикон','Дар ин мақола мо меъёрҳои дақиқии масофаи ҷониби тибири нахи чӯбакро меомӯзем. Дониши дурусти ин масофаҳо барои беҳтар кардани истеъмоли об ва зиёд намудани ҳосил зарур аст.','publish','closed','closed','fosili-tib-jugi-kulaki-andarodho',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
